class ResourceGuard {
    int* handle;
public:
    // Acquisition is Initialization
    ResourceGuard(size_t size) 
        : handle(new int[size]) {}

    // Release happens automatically on scope exit
    ~ResourceGuard() { delete[] handle; }

    // RAII handles exceptions safely:
    // If constructor fails, destructor is not called.
    // If scope code throws, destructor is still called.
};

// Standard Library RAII (Smart Pointer)
struct Payload {};
std::unique_ptr<Payload> p = std::make_unique<Payload>();

// Standard Library RAII (Synchronization)
std::mutex mtx;
void locked_op() {
    std::lock_guard<std::mutex> lock(mtx);
    // Lock automatically released when 'lock' goes out of scope.
}
